-- Objectifs des séances des 5 plans aéro : objectif physiologique (non
-- évalué) + objectif aéro + indicateur de réussite (passages en TT validés,
-- le seul évalué par AeroX), singulier pour un seul passage. 9 langues.

WITH tpl(typ, lang, head) AS (VALUES

('e_cont', 'fr', 'Objectif physiologique : Développer l''endurance fondamentale et la base aérobie. Objectif aéro : Tenir la position TT en endurance (65-72 % FTP), sans se relever pendant les blocs.'),
('e_cont', 'en', 'Physiological goal: Build base endurance and your aerobic base. Aero goal: Hold the TT position at endurance pace (65-72% FTP) without sitting up during the blocks.'),
('e_cont', 'es', 'Objetivo fisiológico: Desarrollar la resistencia básica y la base aeróbica. Objetivo aero: Mantener la posición TT a ritmo de resistencia (65-72 % FTP) sin incorporarte en los bloques.'),
('e_cont', 'it', 'Obiettivo fisiologico: Sviluppare la resistenza di base e la base aerobica. Obiettivo aero: Tenere la posizione TT a ritmo di resistenza (65-72 % FTP) senza rialzarti nei blocchi.'),
('e_cont', 'de', 'Physiologisches Ziel: Grundlagenausdauer und aerobe Basis entwickeln. Aero-Ziel: Die TT-Position im Grundlagentempo (65-72 % FTP) halten, ohne dich in den Blöcken aufzurichten.'),
('e_cont', 'nl', 'Fysiologisch doel: Basisduur en je aerobe basis ontwikkelen. Aerodoel: De TT-houding vasthouden op duurtempo (65-72 % FTP) zonder overeind te komen tijdens de blokken.'),
('e_cont', 'pt', 'Objetivo fisiológico: Desenvolver a resistência de base e a base aeróbia. Objetivo aero: Manter a posição TT em ritmo de resistência (65-72 % FTP) sem levantar o tronco nos blocos.'),
('e_cont', 'ja', '生理学的目標：基礎持久力と有酸素ベースを伸ばす。 エアロ目標：持久ペース（65〜72 % FTP）でTTポジションを保ち、ブロック中は起き上がらない。'),
('e_cont', 'tr', 'Fizyolojik hedef: Temel dayanıklılığı ve aerobik temeli geliştirmek. Aero hedefi: Dayanıklılık temposunda (%65-72 FTP) TT pozisyonunu koru, bloklarda doğrulma.'),
('e_tempo', 'fr', 'Objectif physiologique : Développer l''endurance musculaire au tempo. Objectif aéro : Tenir la position TT au tempo (80-85 % FTP), quand la respiration s''accélère.'),
('e_tempo', 'en', 'Physiological goal: Build muscular endurance at tempo. Aero goal: Hold the TT position at tempo (80-85% FTP), when breathing gets faster.'),
('e_tempo', 'es', 'Objetivo fisiológico: Desarrollar la resistencia muscular a tempo. Objetivo aero: Mantener la posición TT a tempo (80-85 % FTP), cuando la respiración se acelera.'),
('e_tempo', 'it', 'Obiettivo fisiologico: Sviluppare la resistenza muscolare a ritmo tempo. Obiettivo aero: Tenere la posizione TT a ritmo tempo (80-85 % FTP), quando il respiro accelera.'),
('e_tempo', 'de', 'Physiologisches Ziel: Kraftausdauer im Tempobereich entwickeln. Aero-Ziel: Die TT-Position im Tempobereich (80-85 % FTP) halten, wenn die Atmung schneller wird.'),
('e_tempo', 'nl', 'Fysiologisch doel: Spieruithouding op tempo ontwikkelen. Aerodoel: De TT-houding vasthouden op tempo (80-85 % FTP), als de ademhaling versnelt.'),
('e_tempo', 'pt', 'Objetivo fisiológico: Desenvolver a resistência muscular em ritmo tempo. Objetivo aero: Manter a posição TT em ritmo tempo (80-85 % FTP), quando a respiração acelera.'),
('e_tempo', 'ja', '生理学的目標：テンポで筋持久力を伸ばす。 エアロ目標：呼吸が速くなるテンポ（80〜85 % FTP）でTTポジションを保つ。'),
('e_tempo', 'tr', 'Fizyolojik hedef: Tempoda kas dayanıklılığını geliştirmek. Aero hedefi: Nefes hızlandığında tempoda (%80-85 FTP) TT pozisyonunu koru.'),
('e_long', 'fr', 'Objectif physiologique : Développer la base aérobie et la résistance à la fatigue sur la durée. Objectif aéro : Accumuler le plus long temps en TT de la semaine à 70-72 % FTP.'),
('e_long', 'en', 'Physiological goal: Build your aerobic base and fatigue resistance over time. Aero goal: Build up the longest TT time of the week at 70-72% FTP.'),
('e_long', 'es', 'Objetivo fisiológico: Desarrollar la base aeróbica y la resistencia a la fatiga en la duración. Objetivo aero: Acumular el mayor tiempo en TT de la semana al 70-72 % FTP.'),
('e_long', 'it', 'Obiettivo fisiologico: Sviluppare la base aerobica e la resistenza alla fatica sulla durata. Obiettivo aero: Accumulare il tempo in TT più lungo della settimana al 70-72 % FTP.'),
('e_long', 'de', 'Physiologisches Ziel: Aerobe Basis und Ermüdungsresistenz über die Dauer entwickeln. Aero-Ziel: Die längste TT-Zeit der Woche bei 70-72 % FTP sammeln.'),
('e_long', 'nl', 'Fysiologisch doel: Je aerobe basis en weerstand tegen vermoeidheid over de duur ontwikkelen. Aerodoel: De langste TT-tijd van de week opbouwen op 70-72 % FTP.'),
('e_long', 'pt', 'Objetivo fisiológico: Desenvolver a base aeróbia e a resistência à fadiga na duração. Objetivo aero: Acumular o maior tempo em TT da semana a 70-72 % FTP.'),
('e_long', 'ja', '生理学的目標：有酸素ベースと長時間の疲労耐性を伸ばす。 エアロ目標：70〜72 % FTPで週で最も長いTT時間を積み上げる。'),
('e_long', 'tr', 'Fizyolojik hedef: Aerobik temeli ve uzun sürede yorgunluğa direnci geliştirmek. Aero hedefi: %70-72 FTP''de haftanın en uzun TT süresini biriktir.'),
('s_sprint', 'fr', 'Objectif physiologique : Développer la puissance maximale et l''explosivité. Objectif aéro : Sortir la puissance maximale sans quitter la position TT (sprints ≥ 160 % FTP).'),
('s_sprint', 'en', 'Physiological goal: Build maximal power and explosiveness. Aero goal: Produce maximal power without leaving the TT position (sprints ≥ 160% FTP).'),
('s_sprint', 'es', 'Objetivo fisiológico: Desarrollar la potencia máxima y la explosividad. Objetivo aero: Sacar la potencia máxima sin dejar la posición TT (sprints ≥ 160 % FTP).'),
('s_sprint', 'it', 'Obiettivo fisiologico: Sviluppare la potenza massima e l''esplosività. Obiettivo aero: Esprimere la potenza massima senza lasciare la posizione TT (sprint ≥ 160 % FTP).'),
('s_sprint', 'de', 'Physiologisches Ziel: Maximalleistung und Explosivität entwickeln. Aero-Ziel: Maximale Leistung bringen, ohne die TT-Position zu verlassen (Sprints ≥ 160 % FTP).'),
('s_sprint', 'nl', 'Fysiologisch doel: Maximaal vermogen en explosiviteit ontwikkelen. Aerodoel: Maximaal vermogen leveren zonder de TT-houding te verlaten (sprints ≥ 160 % FTP).'),
('s_sprint', 'pt', 'Objetivo fisiológico: Desenvolver a potência máxima e a explosividade. Objetivo aero: Produzir a potência máxima sem sair da posição TT (sprints ≥ 160 % FTP).'),
('s_sprint', 'ja', '生理学的目標：最大パワーと爆発力を伸ばす。 エアロ目標：TTポジションのまま最大パワーを出す（スプリント160 % FTP以上）。'),
('s_sprint', 'tr', 'Fizyolojik hedef: Maksimum gücü ve patlayıcılığı geliştirmek. Aero hedefi: TT pozisyonundan çıkmadan maksimum güç üret (sprintler ≥ %160 FTP).'),
('s_relance', 'fr', 'Objectif physiologique : Développer la capacité anaérobie et la répétition des accélérations. Objectif aéro : Relancer à 115-125 % FTP en restant en TT, comme après un virage ou une bosse.'),
('s_relance', 'en', 'Physiological goal: Build anaerobic capacity and repeated accelerations. Aero goal: Surge at 115-125% FTP while staying in TT, like after a corner or a rise.'),
('s_relance', 'es', 'Objetivo fisiológico: Desarrollar la capacidad anaeróbica y la repetición de aceleraciones. Objetivo aero: Acelerar al 115-125 % FTP sin salir del TT, como tras una curva o un repecho.'),
('s_relance', 'it', 'Obiettivo fisiologico: Sviluppare la capacità anaerobica e la ripetizione delle accelerazioni. Obiettivo aero: Rilanciare al 115-125 % FTP restando in TT, come dopo una curva o uno strappo.'),
('s_relance', 'de', 'Physiologisches Ziel: Anaerobe Kapazität und wiederholte Beschleunigungen entwickeln. Aero-Ziel: Bei 115-125 % FTP antreten und in TT bleiben, wie nach einer Kurve oder Welle.'),
('s_relance', 'nl', 'Fysiologisch doel: Anaerobe capaciteit en herhaalde versnellingen ontwikkelen. Aerodoel: Versnellen op 115-125 % FTP in TT, zoals na een bocht of heuveltje.'),
('s_relance', 'pt', 'Objetivo fisiológico: Desenvolver a capacidade anaeróbia e a repetição de acelerações. Objetivo aero: Retomar a 115-125 % FTP sem sair do TT, como depois de uma curva ou subida.'),
('s_relance', 'ja', '生理学的目標：無酸素能力と加速の反復力を伸ばす。 エアロ目標：カーブや登りの後のように、TTのまま115〜125 % FTPで加速する。'),
('s_relance', 'tr', 'Fizyolojik hedef: Anaerobik kapasiteyi ve tekrarlı hızlanmaları geliştirmek. Aero hedefi: Bir viraj ya da yokuş sonrası gibi TT''de kalarak %115-125 FTP''de atak yap.'),
('s_3030', 'fr', 'Objectif physiologique : Développer la puissance au-dessus de la PMA et la capacité anaérobie. Objectif aéro : Enchaîner des efforts de 30 s à 130 % FTP en TT, récupérations comprises.'),
('s_3030', 'en', 'Physiological goal: Build power above VO2max and anaerobic capacity. Aero goal: String together 30 s efforts at 130% FTP in TT, recoveries included.'),
('s_3030', 'es', 'Objetivo fisiológico: Desarrollar la potencia por encima del VO2max y la capacidad anaeróbica. Objetivo aero: Encadenar esfuerzos de 30 s al 130 % FTP en TT, recuperaciones incluidas.'),
('s_3030', 'it', 'Obiettivo fisiologico: Sviluppare la potenza sopra il VO2max e la capacità anaerobica. Obiettivo aero: Concatenare sforzi di 30 s al 130 % FTP in TT, recuperi compresi.'),
('s_3030', 'de', 'Physiologisches Ziel: Leistung über VO2max und anaerobe Kapazität entwickeln. Aero-Ziel: 30-s-Belastungen bei 130 % FTP in TT aneinanderreihen, Erholungen inklusive.'),
('s_3030', 'nl', 'Fysiologisch doel: Vermogen boven VO2max en anaerobe capaciteit ontwikkelen. Aerodoel: Inspanningen van 30 s op 130 % FTP in TT aaneenrijgen, herstel inbegrepen.'),
('s_3030', 'pt', 'Objetivo fisiológico: Desenvolver a potência acima do VO2max e a capacidade anaeróbia. Objetivo aero: Encadear esforços de 30 s a 130 % FTP em TT, recuperações incluídas.'),
('s_3030', 'ja', '生理学的目標：VO2max以上のパワーと無酸素能力を伸ばす。 エアロ目標：回復も含め、130 % FTPの30秒努力をTTで連続して行う。'),
('s_3030', 'tr', 'Fizyolojik hedef: VO2max üstü gücü ve anaerobik kapasiteyi geliştirmek. Aero hedefi: Toparlanmalar dahil, TT''de %130 FTP''de 30 sn''lik eforları art arda yap.'),
('t_ss', 'fr', 'Objectif physiologique : Faire monter la FTP avec une fatigue mesurée. Objectif aéro : Tenir la position TT à 88-92 % FTP sur des blocs longs.'),
('t_ss', 'en', 'Physiological goal: Raise your FTP with moderate fatigue. Aero goal: Hold the TT position at 88-92% FTP over long blocks.'),
('t_ss', 'es', 'Objetivo fisiológico: Subir la FTP con una fatiga moderada. Objetivo aero: Mantener la posición TT al 88-92 % FTP en bloques largos.'),
('t_ss', 'it', 'Obiettivo fisiologico: Alzare la FTP con una fatica misurata. Obiettivo aero: Tenere la posizione TT all''88-92 % FTP su blocchi lunghi.'),
('t_ss', 'de', 'Physiologisches Ziel: Die FTP bei moderater Ermüdung steigern. Aero-Ziel: Die TT-Position bei 88-92 % FTP über lange Blöcke halten.'),
('t_ss', 'nl', 'Fysiologisch doel: Je FTP verhogen met beperkte vermoeidheid. Aerodoel: De TT-houding vasthouden op 88-92 % FTP over lange blokken.'),
('t_ss', 'pt', 'Objetivo fisiológico: Aumentar a FTP com fadiga moderada. Objetivo aero: Manter a posição TT a 88-92 % FTP em blocos longos.'),
('t_ss', 'ja', '生理学的目標：疲労を抑えてFTPを高める。 エアロ目標：長いブロックで88〜92 % FTPのTTポジションを保つ。'),
('t_ss', 'tr', 'Fizyolojik hedef: Ölçülü yorgunlukla FTP''yi yükseltmek. Aero hedefi: Uzun bloklarda %88-92 FTP''de TT pozisyonunu koru.'),
('t_thr', 'fr', 'Objectif physiologique : Faire monter la FTP. Objectif aéro : Tenir la position TT au seuil (95-100 % FTP).'),
('t_thr', 'en', 'Physiological goal: Raise your FTP. Aero goal: Hold the TT position at threshold (95-100% FTP).'),
('t_thr', 'es', 'Objetivo fisiológico: Subir la FTP. Objetivo aero: Mantener la posición TT en el umbral (95-100 % FTP).'),
('t_thr', 'it', 'Obiettivo fisiologico: Alzare la FTP. Obiettivo aero: Tenere la posizione TT alla soglia (95-100 % FTP).'),
('t_thr', 'de', 'Physiologisches Ziel: Die FTP steigern. Aero-Ziel: Die TT-Position an der Schwelle (95-100 % FTP) halten.'),
('t_thr', 'nl', 'Fysiologisch doel: Je FTP verhogen. Aerodoel: De TT-houding vasthouden op drempel (95-100 % FTP).'),
('t_thr', 'pt', 'Objetivo fisiológico: Aumentar a FTP. Objetivo aero: Manter a posição TT no limiar (95-100 % FTP).'),
('t_thr', 'ja', '生理学的目標：FTPを高める。 エアロ目標：閾値（95〜100 % FTP）でTTポジションを保つ。'),
('t_thr', 'tr', 'Fizyolojik hedef: FTP''yi yükseltmek. Aero hedefi: Eşikte (%95-100 FTP) TT pozisyonunu koru.'),
('t_ou', 'fr', 'Objectif physiologique : Faire monter la puissance critique et la tolérance aux variations autour du seuil. Objectif aéro : Alterner 1'' à 108 % et 1'' à 95 % FTP sans quitter la position TT.'),
('t_ou', 'en', 'Physiological goal: Raise critical power and tolerance to surges around threshold. Aero goal: Alternate 1'' at 108% and 1'' at 95% FTP without leaving the TT position.'),
('t_ou', 'es', 'Objetivo fisiológico: Subir la potencia crítica y la tolerancia a los cambios alrededor del umbral. Objetivo aero: Alternar 1'' al 108 % y 1'' al 95 % FTP sin dejar la posición TT.'),
('t_ou', 'it', 'Obiettivo fisiologico: Alzare la potenza critica e la tolleranza alle variazioni attorno alla soglia. Obiettivo aero: Alternare 1'' al 108 % e 1'' al 95 % FTP senza lasciare la posizione TT.'),
('t_ou', 'de', 'Physiologisches Ziel: Kritische Leistung und Toleranz für Wechsel um die Schwelle steigern. Aero-Ziel: 1'' bei 108 % und 1'' bei 95 % FTP abwechseln, ohne die TT-Position zu verlassen.'),
('t_ou', 'nl', 'Fysiologisch doel: Kritisch vermogen en tolerantie voor wisselingen rond de drempel verhogen. Aerodoel: 1'' op 108 % en 1'' op 95 % FTP afwisselen zonder de TT-houding te verlaten.'),
('t_ou', 'pt', 'Objetivo fisiológico: Aumentar a potência crítica e a tolerância às variações em torno do limiar. Objetivo aero: Alternar 1'' a 108 % e 1'' a 95 % FTP sem sair da posição TT.'),
('t_ou', 'ja', '生理学的目標：クリティカルパワーと閾値付近の変化への耐性を高める。 エアロ目標：TTポジションのまま108 %と95 % FTPを1分ずつ交互に。'),
('t_ou', 'tr', 'Fizyolojik hedef: Kritik gücü ve eşik çevresindeki değişimlere toleransı yükseltmek. Aero hedefi: TT pozisyonundan çıkmadan 1'' %108 ve 1'' %95 FTP dönüşümlü.'),
('t_cp', 'fr', 'Objectif physiologique : Faire monter la puissance critique. Objectif aéro : Tenir la position TT à 108-115 % FTP sur des efforts de 3 à 4 minutes.'),
('t_cp', 'en', 'Physiological goal: Raise your critical power. Aero goal: Hold the TT position at 108-115% FTP over 3 to 4 minute efforts.'),
('t_cp', 'es', 'Objetivo fisiológico: Subir la potencia crítica. Objetivo aero: Mantener la posición TT al 108-115 % FTP en esfuerzos de 3 a 4 minutos.'),
('t_cp', 'it', 'Obiettivo fisiologico: Alzare la potenza critica. Obiettivo aero: Tenere la posizione TT al 108-115 % FTP su sforzi da 3 a 4 minuti.'),
('t_cp', 'de', 'Physiologisches Ziel: Die kritische Leistung steigern. Aero-Ziel: Die TT-Position bei 108-115 % FTP über 3 bis 4 Minuten halten.'),
('t_cp', 'nl', 'Fysiologisch doel: Je kritisch vermogen verhogen. Aerodoel: De TT-houding vasthouden op 108-115 % FTP bij inspanningen van 3 tot 4 minuten.'),
('t_cp', 'pt', 'Objetivo fisiológico: Aumentar a potência crítica. Objetivo aero: Manter a posição TT a 108-115 % FTP em esforços de 3 a 4 minutos.'),
('t_cp', 'ja', '生理学的目標：クリティカルパワーを高める。 エアロ目標：3〜4分の努力で108〜115 % FTPのTTポジションを保つ。'),
('t_cp', 'tr', 'Fizyolojik hedef: Kritik gücü yükseltmek. Aero hedefi: 3-4 dakikalık eforlarda %108-115 FTP''de TT pozisyonunu koru.'),
('v_44', 'fr', 'Objectif physiologique : Développer la PMA (VO2max). Objectif aéro : Rester en position TT pendant chaque récupération de PMA et sur le bloc final à 70 % FTP, souffle court compris.'),
('v_44', 'en', 'Physiological goal: Build your VO2max. Aero goal: Stay in the TT position during every VO2max recovery and the final block at 70% FTP, even when out of breath.'),
('v_44', 'es', 'Objetivo fisiológico: Desarrollar el VO2max. Objetivo aero: Mantener la posición TT en cada recuperación de VO2max y en el bloque final al 70 % FTP, aun sin aliento.'),
('v_44', 'it', 'Obiettivo fisiologico: Sviluppare il VO2max. Obiettivo aero: Restare in posizione TT in ogni recupero di VO2max e nel blocco finale al 70 % FTP, anche col fiato corto.'),
('v_44', 'de', 'Physiologisches Ziel: Die VO2max entwickeln. Aero-Ziel: In jeder VO2max-Erholung und im Schlussblock bei 70 % FTP in TT-Position bleiben, auch wenn die Luft knapp ist.'),
('v_44', 'nl', 'Fysiologisch doel: Je VO2max ontwikkelen. Aerodoel: In TT-houding blijven tijdens elk VO2max-herstel en het slotblok op 70 % FTP, ook als je adem tekortkomt.'),
('v_44', 'pt', 'Objetivo fisiológico: Desenvolver o VO2max. Objetivo aero: Ficar na posição TT em cada recuperação de VO2max e no bloco final a 70 % FTP, mesmo sem fôlego.'),
('v_44', 'ja', '生理学的目標：VO2maxを伸ばす。 エアロ目標：息が苦しくても、VO2maxの回復と最後の70 % FTPブロックではTTポジションを保つ。'),
('v_44', 'tr', 'Fizyolojik hedef: VO2max''ı geliştirmek. Aero hedefi: Nefesin kesik olsa da her VO2max toparlanmasında ve %70 FTP''deki son blokta TT pozisyonunda kal.'),
('v_3015', 'fr', 'Objectif physiologique : Accumuler du temps près de la VO2max. Objectif aéro : Reprendre la position TT en moins de 5 s après chaque effort de 30 s et la garder sur les 15 s de récupération.'),
('v_3015', 'en', 'Physiological goal: Build time close to VO2max. Aero goal: Get back into TT within 5 s after each 30 s effort and keep it through the 15 s recovery.'),
('v_3015', 'es', 'Objetivo fisiológico: Acumular tiempo cerca del VO2max. Objetivo aero: Volver al TT en menos de 5 s tras cada esfuerzo de 30 s y mantenerlo durante los 15 s de recuperación.'),
('v_3015', 'it', 'Obiettivo fisiologico: Accumulare tempo vicino al VO2max. Obiettivo aero: Riprendere la posizione TT entro 5 s da ogni sforzo di 30 s e tenerla nei 15 s di recupero.'),
('v_3015', 'de', 'Physiologisches Ziel: Zeit nahe der VO2max sammeln. Aero-Ziel: Nach jeder 30-s-Belastung binnen 5 s zurück in TT und die 15 s Erholung darin bleiben.'),
('v_3015', 'nl', 'Fysiologisch doel: Tijd dicht bij VO2max opbouwen. Aerodoel: Binnen 5 s na elke inspanning van 30 s terug in TT en die houden tijdens de 15 s herstel.'),
('v_3015', 'pt', 'Objetivo fisiológico: Acumular tempo perto do VO2max. Objetivo aero: Voltar ao TT em menos de 5 s após cada esforço de 30 s e mantê-lo nos 15 s de recuperação.'),
('v_3015', 'ja', '生理学的目標：VO2max付近の時間を積み上げる。 エアロ目標：30秒の努力のたびに5秒以内にTTへ戻り、15秒の回復の間保つ。'),
('v_3015', 'tr', 'Fizyolojik hedef: VO2max yakınında süre biriktirmek. Aero hedefi: Her 30 sn''lik efordan sonra 5 sn içinde TT''ye dön ve 15 sn''lik toparlanma boyunca koru.'),
('b_thr', 'fr', 'Objectif physiologique : Faire monter la FTP. Objectif aéro : Récupérer en TT entre les blocs au seuil et tenir le bloc final à 70 % FTP en TT.'),
('b_thr', 'en', 'Physiological goal: Raise your FTP. Aero goal: Recover in TT between threshold blocks and hold the final block at 70% FTP in TT.'),
('b_thr', 'es', 'Objetivo fisiológico: Subir la FTP. Objetivo aero: Recuperar en TT entre los bloques de umbral y mantener el bloque final al 70 % FTP en TT.'),
('b_thr', 'it', 'Obiettivo fisiologico: Alzare la FTP. Obiettivo aero: Recuperare in TT tra i blocchi alla soglia e tenere il blocco finale al 70 % FTP in TT.'),
('b_thr', 'de', 'Physiologisches Ziel: Die FTP steigern. Aero-Ziel: Zwischen den Schwellenblöcken in TT erholen und den Schlussblock bei 70 % FTP in TT halten.'),
('b_thr', 'nl', 'Fysiologisch doel: Je FTP verhogen. Aerodoel: In TT herstellen tussen de drempelblokken en het slotblok op 70 % FTP in TT vasthouden.'),
('b_thr', 'pt', 'Objetivo fisiológico: Aumentar a FTP. Objetivo aero: Recuperar em TT entre os blocos de limiar e manter o bloco final a 70 % FTP em TT.'),
('b_thr', 'ja', '生理学的目標：FTPを高める。 エアロ目標：閾値ブロックの間はTTで回復し、最後の70 % FTPブロックをTTで保つ。'),
('b_thr', 'tr', 'Fizyolojik hedef: FTP''yi yükseltmek. Aero hedefi: Eşik blokları arasında TT''de toparlanmak ve %70 FTP''deki son bloğu TT''de korumak.'),
('b_vo2', 'fr', 'Objectif physiologique : Développer la PMA (VO2max). Objectif aéro : Récupérer en TT entre les efforts et tenir le bloc final à 70 % FTP en TT.'),
('b_vo2', 'en', 'Physiological goal: Build your VO2max. Aero goal: Recover in TT between efforts and hold the final block at 70% FTP in TT.'),
('b_vo2', 'es', 'Objetivo fisiológico: Desarrollar el VO2max. Objetivo aero: Recuperar en TT entre esfuerzos y mantener el bloque final al 70 % FTP en TT.'),
('b_vo2', 'it', 'Obiettivo fisiologico: Sviluppare il VO2max. Obiettivo aero: Recuperare in TT tra gli sforzi e tenere il blocco finale al 70 % FTP in TT.'),
('b_vo2', 'de', 'Physiologisches Ziel: Die VO2max entwickeln. Aero-Ziel: Zwischen den Belastungen in TT erholen und den Schlussblock bei 70 % FTP in TT halten.'),
('b_vo2', 'nl', 'Fysiologisch doel: Je VO2max ontwikkelen. Aerodoel: In TT herstellen tussen de inspanningen en het slotblok op 70 % FTP in TT vasthouden.'),
('b_vo2', 'pt', 'Objetivo fisiológico: Desenvolver o VO2max. Objetivo aero: Recuperar em TT entre os esforços e manter o bloco final a 70 % FTP em TT.'),
('b_vo2', 'ja', '生理学的目標：VO2maxを伸ばす。 エアロ目標：努力の間はTTで回復し、最後の70 % FTPブロックをTTで保つ。'),
('b_vo2', 'tr', 'Fizyolojik hedef: VO2max''ı geliştirmek. Aero hedefi: Eforlar arasında TT''de toparlanmak ve %70 FTP''deki son bloğu TT''de korumak.'),
('b_vo2aero', 'fr', 'Objectif physiologique : Développer la PMA (VO2max). Objectif aéro : Tenir la position TT même au-dessus du seuil, efforts et récupérations compris.'),
('b_vo2aero', 'en', 'Physiological goal: Build your VO2max. Aero goal: Hold the TT position even above threshold, efforts and recoveries included.'),
('b_vo2aero', 'es', 'Objetivo fisiológico: Desarrollar el VO2max. Objetivo aero: Mantener la posición TT incluso por encima del umbral, esfuerzos y recuperaciones incluidos.'),
('b_vo2aero', 'it', 'Obiettivo fisiologico: Sviluppare il VO2max. Obiettivo aero: Tenere la posizione TT anche sopra la soglia, sforzi e recuperi compresi.'),
('b_vo2aero', 'de', 'Physiologisches Ziel: Die VO2max entwickeln. Aero-Ziel: Die TT-Position auch über der Schwelle halten, Belastungen und Erholungen inklusive.'),
('b_vo2aero', 'nl', 'Fysiologisch doel: Je VO2max ontwikkelen. Aerodoel: De TT-houding ook boven de drempel vasthouden, inspanningen en herstel inbegrepen.'),
('b_vo2aero', 'pt', 'Objetivo fisiológico: Desenvolver o VO2max. Objetivo aero: Manter a posição TT mesmo acima do limiar, esforços e recuperações incluídos.'),
('b_vo2aero', 'ja', '生理学的目標：VO2maxを伸ばす。 エアロ目標：努力も回復も含め、閾値を超えてもTTポジションを保つ。'),
('b_vo2aero', 'tr', 'Fizyolojik hedef: VO2max''ı geliştirmek. Aero hedefi: Eforlar ve toparlanmalar dahil, eşiğin üzerinde bile TT pozisyonunu korumak.'),
('b_alt', 'fr', 'Objectif physiologique : Développer l''endurance fondamentale et la base aérobie. Objectif aéro : Tenir chaque bloc en TT à 72 % FTP ; seule la position change avec le relevé, pas la puissance.'),
('b_alt', 'en', 'Physiological goal: Build base endurance and your aerobic base. Aero goal: Hold every block in TT at 72% FTP; only the position changes when upright, not the power.'),
('b_alt', 'es', 'Objetivo fisiológico: Desarrollar la resistencia básica y la base aeróbica. Objetivo aero: Mantener cada bloque en TT al 72 % FTP; solo cambia la posición al incorporarte, no la potencia.'),
('b_alt', 'it', 'Obiettivo fisiologico: Sviluppare la resistenza di base e la base aerobica. Obiettivo aero: Tenere ogni blocco in TT al 72 % FTP; cambia solo la posizione da eretto, non la potenza.'),
('b_alt', 'de', 'Physiologisches Ziel: Grundlagenausdauer und aerobe Basis entwickeln. Aero-Ziel: Jeden Block bei 72 % FTP in TT halten; aufrecht ändert sich nur die Position, nicht die Leistung.'),
('b_alt', 'nl', 'Fysiologisch doel: Basisduur en je aerobe basis ontwikkelen. Aerodoel: Elk blok in TT op 72 % FTP vasthouden; rechtop verandert alleen de houding, niet het vermogen.'),
('b_alt', 'pt', 'Objetivo fisiológico: Desenvolver a resistência de base e a base aeróbia. Objetivo aero: Manter cada bloco em TT a 72 % FTP; ereto só muda a posição, não a potência.'),
('b_alt', 'ja', '生理学的目標：基礎持久力と有酸素ベースを伸ばす。 エアロ目標：各ブロックを72 % FTPでTTに保つ。アップライトで変わるのは姿勢だけでパワーは同じ。'),
('b_alt', 'tr', 'Fizyolojik hedef: Temel dayanıklılığı ve aerobik temeli geliştirmek. Aero hedefi: Her bloğu %72 FTP''de TT''de korumak; dik konumda sadece pozisyon değişir, güç değişmez.'),
('b_long', 'fr', 'Objectif physiologique : Développer la base aérobie et la résistance à la fatigue sur la durée. Objectif aéro : Tenir les blocs TT les plus longs de la semaine à 72 % FTP.'),
('b_long', 'en', 'Physiological goal: Build your aerobic base and fatigue resistance over time. Aero goal: Hold the longest TT blocks of the week at 72% FTP.'),
('b_long', 'es', 'Objetivo fisiológico: Desarrollar la base aeróbica y la resistencia a la fatiga en la duración. Objetivo aero: Mantener los bloques TT más largos de la semana al 72 % FTP.'),
('b_long', 'it', 'Obiettivo fisiologico: Sviluppare la base aerobica e la resistenza alla fatica sulla durata. Obiettivo aero: Tenere i blocchi TT più lunghi della settimana al 72 % FTP.'),
('b_long', 'de', 'Physiologisches Ziel: Aerobe Basis und Ermüdungsresistenz über die Dauer entwickeln. Aero-Ziel: Die längsten TT-Blöcke der Woche bei 72 % FTP halten.'),
('b_long', 'nl', 'Fysiologisch doel: Je aerobe basis en weerstand tegen vermoeidheid over de duur ontwikkelen. Aerodoel: De langste TT-blokken van de week op 72 % FTP vasthouden.'),
('b_long', 'pt', 'Objetivo fisiológico: Desenvolver a base aeróbia e a resistência à fadiga na duração. Objetivo aero: Manter os blocos TT mais longos da semana a 72 % FTP.'),
('b_long', 'ja', '生理学的目標：有酸素ベースと長時間の疲労耐性を伸ばす。 エアロ目標：72 % FTPで週で最も長いTTブロックを保つ。'),
('b_long', 'tr', 'Fizyolojik hedef: Aerobik temeli ve uzun sürede yorgunluğa direnci geliştirmek. Aero hedefi: Haftanın en uzun TT bloklarını %72 FTP''de korumak.'),
('b_ss', 'fr', 'Objectif physiologique : Entretenir la FTP en semaine d''assimilation. Objectif aéro : Récupérer en TT entre les blocs au seuil et tenir le bloc final à 70 % FTP en TT.'),
('b_ss', 'en', 'Physiological goal: Maintain your FTP during the recovery week. Aero goal: Recover in TT between threshold blocks and hold the final block at 70% FTP in TT.'),
('b_ss', 'es', 'Objetivo fisiológico: Mantener la FTP en la semana de asimilación. Objetivo aero: Recuperar en TT entre los bloques de umbral y mantener el bloque final al 70 % FTP en TT.'),
('b_ss', 'it', 'Obiettivo fisiologico: Mantenere la FTP nella settimana di scarico. Obiettivo aero: Recuperare in TT tra i blocchi alla soglia e tenere il blocco finale al 70 % FTP in TT.'),
('b_ss', 'de', 'Physiologisches Ziel: Die FTP in der Entlastungswoche erhalten. Aero-Ziel: Zwischen den Schwellenblöcken in TT erholen und den Schlussblock bei 70 % FTP in TT halten.'),
('b_ss', 'nl', 'Fysiologisch doel: Je FTP onderhouden in de herstelweek. Aerodoel: In TT herstellen tussen de drempelblokken en het slotblok op 70 % FTP in TT vasthouden.'),
('b_ss', 'pt', 'Objetivo fisiológico: Manter a FTP na semana de assimilação. Objetivo aero: Recuperar em TT entre os blocos de limiar e manter o bloco final a 70 % FTP em TT.'),
('b_ss', 'ja', '生理学的目標：回復週にFTPを維持する。 エアロ目標：閾値ブロックの間はTTで回復し、最後の70 % FTPブロックをTTで保つ。'),
('b_ss', 'tr', 'Fizyolojik hedef: Toparlanma haftasında FTP''yi korumak. Aero hedefi: Eşik blokları arasında TT''de toparlanmak ve %70 FTP''deki son bloğu TT''de korumak.'),
('b_45', 'fr', 'Objectif physiologique : Consolider l''endurance fondamentale. Objectif aéro : Tenir 45 minutes d''affilée en TT à 72 % FTP.'),
('b_45', 'en', 'Physiological goal: Consolidate base endurance. Aero goal: Hold 45 minutes in a row in TT at 72% FTP.'),
('b_45', 'es', 'Objetivo fisiológico: Consolidar la resistencia básica. Objetivo aero: Mantener 45 minutos seguidos en TT al 72 % FTP.'),
('b_45', 'it', 'Obiettivo fisiologico: Consolidare la resistenza di base. Obiettivo aero: Tenere 45 minuti di fila in TT al 72 % FTP.'),
('b_45', 'de', 'Physiologisches Ziel: Die Grundlagenausdauer festigen. Aero-Ziel: 45 Minuten am Stück in TT bei 72 % FTP halten.'),
('b_45', 'nl', 'Fysiologisch doel: De basisduur consolideren. Aerodoel: 45 minuten aan één stuk in TT op 72 % FTP vasthouden.'),
('b_45', 'pt', 'Objetivo fisiológico: Consolidar a resistência de base. Objetivo aero: Manter 45 minutos seguidos em TT a 72 % FTP.'),
('b_45', 'ja', '生理学的目標：基礎持久力を固める。 エアロ目標：72 % FTPでTTを45分連続で保つ。'),
('b_45', 'tr', 'Fizyolojik hedef: Temel dayanıklılığı pekiştirmek. Aero hedefi: %72 FTP''de aralıksız 45 dakika TT''de kalmak.')
), ind(lang, many, one) AS (VALUES ('fr', 'Réussite : {k} passages en TT validés (≥ 95 % du passage en TT, aucune sortie de 20 s ou plus).', 'Réussite : 1 passage en TT validé (≥ 95 % du passage en TT, aucune sortie de 20 s ou plus).'), ('en', 'Success: {k} TT blocks validated (≥ 95% of the block in TT, no exit of 20 s or more).', 'Success: 1 TT block validated (≥ 95% of the block in TT, no exit of 20 s or more).'), ('es', 'Éxito: {k} tramos en TT validados (≥ 95 % del tramo en TT, ninguna salida de 20 s o más).', 'Éxito: 1 tramo en TT validado (≥ 95 % del tramo en TT, ninguna salida de 20 s o más).'), ('it', 'Riuscita: {k} tratti in TT validati (≥ 95 % del tratto in TT, nessuna uscita di 20 s o più).', 'Riuscita: 1 tratto in TT validato (≥ 95 % del tratto in TT, nessuna uscita di 20 s o più).'), ('de', 'Erfolg: {k} TT-Abschnitte bestanden (≥ 95 % des Abschnitts in TT, kein Verlassen von 20 s oder mehr).', 'Erfolg: 1 TT-Abschnitt bestanden (≥ 95 % des Abschnitts in TT, kein Verlassen von 20 s oder mehr).'), ('nl', 'Geslaagd: {k} TT-stukken gehaald (≥ 95 % van het stuk in TT, geen uitstap van 20 s of langer).', 'Geslaagd: 1 TT-stuk gehaald (≥ 95 % van het stuk in TT, geen uitstap van 20 s of langer).'), ('pt', 'Sucesso: {k} trechos em TT validados (≥ 95 % do trecho em TT, nenhuma saída de 20 s ou mais).', 'Sucesso: 1 trecho em TT validado (≥ 95 % do trecho em TT, nenhuma saída de 20 s ou mais).'), ('ja', '達成条件：TTブロック{k}本を達成（ブロックの95 %以上をTTで、20秒以上の離脱なし）。', '達成条件：TTブロック1本を達成（ブロックの95 %以上をTTで、20秒以上の離脱なし）。'), ('tr', 'Başarı: {k} TT bölümü onaylandı (bölümün ≥ %95''i TT''de, 20 sn veya daha uzun çıkış yok).', 'Başarı: 1 TT bölümü onaylandı (bölümün ≥ %95''i TT''de, 20 sn veya daha uzun çıkış yok).')
