), objs AS (
  SELECT v.session_name,
    (SELECT jsonb_object_agg(t.lang, t.head || ' ' || CASE WHEN v.k = 1 THEN i.one ELSE replace(i.many, '{k}', v.k::text) END)
       FROM tpl t JOIN ind i USING (lang) WHERE t.typ = v.typ) AS obj
  FROM v
)
UPDATE public.training_sessions ts
SET translations_json = jsonb_set(ts.translations_json, '{objectif}', o.obj)
FROM objs o
WHERE ts.name = o.session_name;
